// ===========================================================================
// CASAGENCIA · ASISTENTE DE WHATSAPP — CONFIGURACION COMUN
// ---------------------------------------------------------------------------
// Proyecto independiente del asistente telefonico: sus workflows llevan [WA] y
// no llaman nunca a los [TEL]. Comparten los MISMOS datos (el Google Sheet de
// la cartera y los calendarios de Carmen y Gisela), no el codigo en ejecucion.
//
// Se inyecta al principio de los nodos Code propios de WhatsApp.
// Editar aqui y volver a desplegar:  python3 build_whatsapp.py --deploy
// ===========================================================================
const ZONA = 'Europe/Madrid';

// --- Chatwoot (panel de conversaciones) -------------------------------------
const CHATWOOT_URL    = 'https://panel-casa-agencia.serversvisionarius.com';
const CHATWOOT_CUENTA = 1;   // "Casa Agencia Inmobiliaria"
const CHATWOOT_INBOX  = 1;   // inbox "WhatsApp" (whatsapp_cloud, +34 864 89 37 94)
// Usuario del panel con el que escribe Sara (el del token de la API, "IA Casagencia").
// Lo que escribe cualquier otro usuario lo ha escrito una persona del equipo.
const CHATWOOT_USUARIO_IA = 1;

// --- Meta · WhatsApp Cloud API ---------------------------------------------
// Linea +34 864 89 37 94 (Casa Agencia Inmobiliaria), verificada y conectada.
// El token NO va aqui: esta en la credencial "Meta WhatsApp Casagencia".
const META_API        = 'https://graph.facebook.com/v22.0';
const META_PHONE_ID   = '1254647111075735';
const META_WABA_ID    = '1791979752043585';

// Plantillas aprobadas. OJO con el idioma: bienvenida_alquiler y plantilla_aviso
// estan dadas de alta en INGLES ('en') aunque el texto sea en espanol. Meta
// rechaza el envio si el codigo de idioma no es exactamente el registrado.
// Todas usan parametros por posicion: {{1}}, {{2}} y, en alquiler, {{3}}.
const PLANTILLAS = {
  compra:   { nombre: 'bienvenida_compra',   idioma: 'es' },  // {{1}} nombre, {{2}} enlace del inmueble
  alquiler: { nombre: 'bienvenida_alquiler', idioma: 'en' },  // {{1}} nombre, {{2}} enlace, {{3}} que clase de alquiler
  aviso:    { nombre: 'plantilla_aviso',     idioma: 'en' },  // {{1}} comercial, {{2}} el aviso (una linea)
  abierta:  { nombre: 'plantilla_abierta',   idioma: 'en' },  // {{1}} nombre, {{2}} texto libre (una linea)
};

// El {{3}} de bienvenida_alquiler: va dentro de "*alquiler {{3}}*", en negrita.
// Regla de Paco: que en el PRIMER mensaje quede claro que un temporal no es
// anual y que va por paquetes de meses, y asi no se gastan diez conversaciones
// con gente que busca todo el ano. Lo del empadronamiento NO va aqui: es
// delicado para un primer mensaje a quien todavia no ha dicho nada. Sara lo
// dice en la conversacion (prompt y ficha del inmueble) cuando viene a cuento.
const MODALIDAD_PLANTILLA = {
  larga_duracion: 'de larga duración (para vivir todo el año)',
  temporal: 'SOLO TEMPORAL (únicamente por paquetes de meses, por ejemplo de octubre a junio), '
    + 'no es un alquiler anual, tampoco por meses sueltos',
};
// Ultimo recurso: Meta no acepta un parametro vacio, asi que si alguien manda la
// bienvenida de alquiler sin saber la modalidad (hoy no pasa: los 22 alquileres
// de la cartera la tienen), se dice que esta por confirmar en vez de afirmar
// una de las dos. Los leads de verdad no llegan aqui: decidirPrimerMensaje
// cambia de plantilla antes.
const MODALIDAD_PLANTILLA_SIN_SABER = '(temporal o de larga duración: te lo confirmo enseguida)';

// Texto exacto de cada plantilla, tal y como esta aprobada en Meta. Solo se usa
// para que en el panel se lea lo mismo que le ha llegado al cliente.
const TEXTO_PLANTILLA = {
  bienvenida_compra:
    'Hola *{{1}}*, soy Sara de Casagencia.\nHemos recibido tu solicitud de información por este inmueble de compra: {{2}}\n*Quieres visitar la vivienda?*',
  bienvenida_alquiler:
    'Hola *{{1}}*, soy Sara de Casagencia.\nHemos recibido tu solicitud de información por este inmueble de *alquiler {{3}}*: {{2}}\n*Quieres visitar la vivienda?*',
  plantilla_aviso:
    'Hola *{{1}}*,\n*{{2}}*\nUn saludo. Tenga un buen día.',
  plantilla_abierta:
    'Hola *{{1}}*,\n{{2}}\nUn saludo. Buen día.',
};

// --- El equipo ---------------------------------------------------------------
// Mismo reparto que el telefono: la referencia manda.
const ASESORA_POR_PREFIJO = { BN: 'Carmen', OR: 'Carmen', CS: 'Gisela', VR: 'Gisela' };
const ASESORA_POR_MUNICIPIO = {
  'benicasim': 'Carmen', 'benicassim': 'Carmen', 'oropesa': 'Carmen', 'orpesa': 'Carmen',
  'torreblanca': 'Carmen', 'onda': 'Carmen', 'borriol': 'Carmen', 'vilafames': 'Carmen',
  'castellon': 'Gisela', 'castello': 'Gisela', 'vila-real': 'Gisela', 'villarreal': 'Gisela',
  'burriana': 'Gisela', 'borriana': 'Gisela', 'almazora': 'Gisela', 'almassora': 'Gisela',
  'alquerias': 'Gisela', 'alqueries': 'Gisela',
};
// Moviles a los que llega el aviso por WhatsApp (los mismos que usa el telefono
// para saber por que linea entra la llamada).
const EQUIPO = {
  Carmen:   { movil: '34654907386', email: 'carmen@casagencia.com' },
  Gisela:   { movil: '34690027772', email: 'gisela@casagencia.com' },
  Laurence: { movil: '34618724192', email: 'laurence@casagencia.com' },
};
// La direccion: recibe TODOS los avisos por WhatsApp, ademas de la comercial.
// Los numeros a los que llama la gente. OJO: los de los portales estan
// desviados por el movil de UNA de las comerciales, pero los comparten las dos:
// que una llamada de Idealista pase por el telefono de Carmen no la hace suya.
// Solo es "su linea" si el cliente marco el movil de la comercial.
const LINEAS_ENTRADA = {
  '654907386': 'Carmen', '690027772': 'Gisela', '618724192': 'Laurence',
  '964300986': 'oficina de Benicassim', '964742549': 'oficina de Castellón',
  '864893794': 'número general',
  '864870199': 'Idealista', '936060117': 'Fotocasa', '864870288': 'un portal',
};

const DIRECCION = { nombre: 'Paco', movil: '34662052387' };

// --- WhatsApp de la IA (para enlaces wa.me) -------------------------------------
// El numero de la linea de Sara, sin + ni espacios, para los botones de WhatsApp
// de la web y de los correos.
const WHATSAPP_IA = '34864893794';
const LOGO_CASAGENCIA = 'https://media.egorealestate.com/ORIGINAL/70400c69-431c-46bf-b25d-9ac843eb1b7e.png';
// Mensaje con el que llega quien pulsa la bolita de WhatsApp de casagencia.com
const MENSAJE_BOLITA_WEB = 'Hola, os acabo de ver por la web y estoy interesado en uno de vuestros inmuebles.';

// --- Varias solicitudes de la misma persona -----------------------------------
// Si alguien pide informacion de otro inmueble y ya le escribimos por uno en los
// ultimos OTRA_SOLICITUD_DIAS dias, no se le repite la bienvenida: le sale la
// plantilla abierta "Tambien he visto que te has interesado por este otro
// inmueble: <enlace> ¿Lo quieres tambien visitar?" (TEXTOS_ABIERTA.otro_inmueble
// en leads.js). Sara ve en su contexto todos los que ha pedido.
const OTRA_SOLICITUD_DIAS = 7;
// Como empieza ese mensaje en cada idioma (el seguimiento de 12 h lo trata como
// una bienvenida)
const PREFIJOS_OTRO_INMUEBLE = ['También he visto que te has interesado', "I've also seen that you're interested", "J'ai aussi vu que ce bien"];
// Y como empieza el primer mensaje a un lead de la WEB (TEXTOS_ABIERTA.busqueda
// en leads.js). Tambien sale con la plantilla abierta, pero no hay un inmueble
// concreto, asi que su seguimiento es otro (SEGUIMIENTO.plantilla_web). Los
// prefijos llegan hasta "nuestra web" a proposito: el de captacion de
// propietarios empieza igual ("Soy Sara, IA de Casagencia. Hemos recibido...")
// y ese NO se persigue.
const PREFIJOS_LEAD_WEB = ['Soy Sara, IA de Casagencia. Hemos recibido el mensaje que nos dejaste en nuestra web',
                           "I'm Sara, Casagencia's AI. We received the message you left on our website",
                           "Je suis Sara, l'IA de Casagencia. Nous avons bien reçu votre message sur notre site"];

// --- Seguimiento a quien no contesta a la bienvenida ---------------------------
// Si el cliente no contesta a la plantilla de bienvenida (la conversacion sigue
// en 1-bienvenida_ia y lo ultimo es esa plantilla), a las `horas` se le manda la
// plantilla de seguimiento ({{1}} = su nombre), una sola vez y solo en horario
// comercial: de `desde` a `hasta` (hora de Espana). Si las 12 h se cumplen fuera
// de horario, sale a las 9:00. No se manda si la bienvenida es de hace mas de
// `max_horas` (para no escribir a leads antiguos), si el bot esta en Off o si
// alguien del equipo ya le ha escrito.
//
// Que la conversacion este CERRADA en el panel no lo impide: cerrarla sin
// haberle escrito al cliente es ordenar el panel, no decidir que no se le
// persigue. Si la asesora si le ha escrito, su mensaje es lo ultimo de la
// conversacion y entonces no sale (esa regla no cambia).
//
//   plantilla:     a quien pregunto por un inmueble concreto (portales y web
//                  con referencia). "¿Te sigue interesando visitar el inmueble
//                  o necesitas mas informacion?"
//   plantilla_web: a los leads de la web sin inmueble (TEXTOS_ABIERTA.busqueda),
//                  donde no hay nada que "volver a visitar". Texto propuesto:
//                  "Hola {{1}}, ¿sigues buscando? Cuentame que necesitas y te
//                  enseño lo que tenemos." Mientras no este dada de alta y
//                  aprobada en Meta no se manda nada a esos leads (se reintenta
//                  en cada pasada, hasta max_horas).
const SEGUIMIENTO = { activo: true, plantilla: 'seguimiento_1', plantilla_web: 'seguimiento_web', idioma: 'en', horas: 12, desde: 9, hasta: 19, max_horas: 72 };

// --- Seguimiento a la hora al que se queda parado en una pregunta --------------
// Otro caso distinto del de arriba: aqui el cliente YA contesto (la conversacion
// esta en 2-en_proceso) y se ha quedado callado a mitad de la cualificacion. Si
// lo ultimo es una pregunta de Sara sin contestar desde hace `horas`, se le
// repite ESA MISMA pregunta y la conversacion pasa a 4-intervenir: a partir de
// ahi la lleva una persona. Una sola vez por pregunta.
//
// No es una plantilla de Meta, es un mensaje normal: por eso `max_horas` se
// queda por debajo de las 24 h de la ventana de WhatsApp. Si se pasa de ahi
// (p. ej. se quedo parado un viernes por la tarde), ya no se le escribe: se
// manda fuera de la ventana y Meta lo rechazaria.
const SEGUIMIENTO_PARADO = { activo: true, horas: 1, desde: 9, hasta: 19, max_horas: 20 };
// El idioma de una pregunta que escribio Sara. No vale idiomaDe() de leads.js:
// esa mira el saludo del cliente ("hello", "bonjour") y una pregunta no lo lleva.
// En espanol el '¿' es definitivo; si no, se mira si es frances y si no, ingles.
function idiomaDePregunta(texto) {
  const t = sinAcentos(texto);
  if (/[¿¡]/.test(String(texto ?? ''))) return 'es';
  if (/\b(vous|votre|quel|quelle|combien|est-ce|souhaitez|avez|seriez)\b/.test(t)) return 'fr';
  if (/\b(you|your|how|what|when|which|would|do|are|is)\b/.test(t)) return 'en';
  return 'es';
}
// Como se le vuelve a hacer la pregunta, en su idioma. Por su nombre y sin
// echarle en cara que no ha contestado: nada de "¿sigues ahi?" ni "te repito
// la pregunta", que suena a reproche. Si no sabemos como se llama, igual pero
// sin el nombre.
const TEXTOS_REPETIR = {
  es: (p, n) => (n ? `${n}, cuéntame: ${p}` : `Cuéntame: ${p}`),
  en: (p, n) => (n ? `${n}, tell me: ${p}` : `Tell me: ${p}`),
  fr: (p, n) => (n ? `${n}, dites-moi : ${p}` : `Dites-moi : ${p}`),
};

// --- Recordatorio de la visita AL CLIENTE (24 h y 2 h antes) --------------------
// [WA] 6 (24 h) y [WA] 7 (2 h) miran las agendas de Carmen y Gisela cada 15
// minutos y le mandan al cliente una plantilla de Meta por su conversacion del
// panel. Todas las visitas que tengan el telefono del cliente en el titulo (las
// de WhatsApp y las del telefono). Cada visita se recuerda una sola vez.
//   plantilla:  nombre de la plantilla en Meta ('' = aun no existe: no se manda)
//   activo:     false = solo a los telefonos de prueba
//   parametros: que va en {{1}}, {{2}}... por orden. Disponibles: nombre,
//               hora_texto ("5 de la tarde"), hora ("17:00"),
//               cuando ("manana martes 7 de octubre a las 17:00" / "hoy a las 17:00"),
//               fecha_hora, inmueble, direccion, asesora, referencia
// Si la plantilla aun no esta aprobada en Meta, no se manda y se reintenta.
const RECORDATORIO_CLIENTE = {
  // "Hola {{1}}, Te recuerdo que manana a las {{2}} tenemos una visita agendada.
  //  Me confirmas tu presencia?" + boton "Si, confirmo"
  '24h': { horas: 24, plantilla: 'recordatorio_visita_24h', idioma: 'en', activo: true,
           parametros: ['nombre', 'hora_texto'] },
  // "Hola {{1}}, En 2 horas nos vemos en la visita. Te veo alli."
  '2h':  { horas: 2,  plantilla: 'recordatorio_visita_2h', idioma: 'en', activo: true,
           parametros: ['nombre'] },
};
// Tambien a las PRE-RESERVAS que la asesora aun no ha confirmado (el titulo
// sigue empezando por PRE-RESERVA). false = solo a las confirmadas.
const RECORDAR_PRERESERVAS = true;

// --- Correo a los leads que solo dejan su email ---------------------------------
// La plantilla esta en wa/correo_lead.js. Sale del Gmail de su asesora (Carmen
// o Gisela, credenciales "Conexión Correo ..." en n8n), con respuesta a ella.
// Activo desde el 6-10-2026. Paco va en copia de todos.
const CORREO_LEADS = { activo: true, nombre: 'Sara · Casagencia', copia: 'paco@casagencia.com' };

// --- Leads entrantes ------------------------------------------------------------
// De la WEB salen del buzon formularioscasagencia@gmail.com (credencial "Correo
// Formulario"): solo los de web@websites.egorealestate.com. Los de los PORTALES
// ya entran en eGO y se cogen de su API ([WA] 5).
const BUZON_LEADS = 'formularioscasagencia@gmail.com';
// 'preparado': decide que mandaria y lo apunta (tabla leads_entrantes), pero NO
// manda nada. 'real': manda la plantilla. Se cambia aqui y se vuelve a desplegar.
// En produccion desde el 6-10-2026.
const MODO_LEADS = 'real';
const PORTALES = [
  { nombre: 'Idealista',  de: /idealista\.com/i,   asunto: /idealista/i },
  { nombre: 'Fotocasa',   de: /fotocasa\.es/i,     asunto: /fotocasa/i },
  { nombre: 'Habitaclia', de: /habitaclia\.com/i,  asunto: /habitaclia/i },
  { nombre: 'Web',        de: /casagencia\.com/i,  asunto: /formulario|contacto/i },
];

// --- Etiquetas de Chatwoot ---------------------------------------------------
// Las mismas que Blue, creadas ya en el panel. Las cuatro primeras son el estado
// de la conversacion (solo una a la vez y nunca hacia atras); 4-intervenir se
// suma a la que haya y hace que el bot deje de contestar.
const ETIQUETAS = {
  bienvenida: '1-bienvenida_ia',   // la IA ha mandado la plantilla
  seguimiento: '5-seguimiento_1',  // no contesto a la bienvenida y se le mando el seguimiento de 12 h
  en_proceso: '2-en_proceso',      // el cliente ha contestado y la IA esta con el
  agendada:   '3-agendada_ia',     // visita agendada de verdad en el calendario
  intervenir: '4-intervenir',      // tiene que entrar una persona (la IA sigue contestando: solo se calla con bot = Off)
};
// OJO: el orden de ESTADOS es el del embudo, NO el del numero del nombre. El
// seguimiento va entre la bienvenida y "en proceso" aunque se llame 5-, que es
// como lo tiene puesto el equipo en el panel. Cambiar este orden hace que una
// conversacion pueda volver hacia atras.
const ESTADOS = [ETIQUETAS.bienvenida, ETIQUETAS.seguimiento, ETIQUETAS.en_proceso, ETIQUETAS.agendada];
// Etiquetas que se SUMAN a las de estado (no cuentan como estado):
const ETIQUETA_VENDEDOR = 'vendedor';               // el comprador tiene que vender una vivienda
const ETIQUETA_LLAMADA  = '0-llamada_telefonica';   // la conversacion tiene llamadas del asistente telefonico

// --- Enlaces que el telefono manda por WhatsApp -------------------------------
// En una llamada NO se puede dictar una direccion web: se manda por WhatsApp con
// la plantilla abierta. Los enlaces salen de wa_cartera, nunca del modelo.
const ENLACES_TELEFONO = { max: 3 };
const TEXTOS_ENLACES_TEL = {
  es: { uno: 'te paso el enlace del inmueble del que hemos hablado por teléfono:',
        varios: 'te paso los enlaces de los inmuebles de los que hemos hablado por teléfono:',
        cierre_uno: ' ¿Quieres que te organicemos una visita?',
        cierre_varios: ' ¿Quieres visitar alguno?',
        por: 'por', al_mes: ' al mes' },
  en: { uno: "here's the link to the property we talked about on the phone:",
        varios: "here are the links to the properties we talked about on the phone:",
        cierre_uno: ' Would you like us to arrange a viewing?',
        cierre_varios: ' Would you like to visit any of them?',
        por: 'for', al_mes: ' per month' },
  fr: { uno: 'voici le lien du bien dont nous avons parlé au téléphone :',
        varios: 'voici les liens des biens dont nous avons parlé au téléphone :',
        cierre_uno: ' Souhaitez-vous que nous organisions une visite ?',
        cierre_varios: ' Souhaitez-vous en visiter un ?',
        por: 'à', al_mes: ' par mois' },
};

// --- El interruptor del bot (atributo "bot" del contacto, como en Blue) -------
// Off: la IA se calla (se cambia a mano en el panel). On o sin valor ("Select
// value"): la IA contesta. Con SOLO_CONTACTOS_CON_BOT = true solo contestaria a
// los contactos con el atributo puesto (el estandar de Blue); Casagencia quiere
// que conteste a todos menos a los que esten en Off.
const SOLO_CONTACTOS_CON_BOT = false;

// --- Asignacion de la conversacion en Chatwoot (como el reparto del telefono) -
// Id de cada comercial como agente del panel. La conversacion se asigna a la
// asesora de la referencia (BN/OR Carmen, CS/VR Gisela; si no hay, Laurence),
// salvo que ya la tenga una de ellas: un cambio hecho a mano se respeta.
const AGENTES_CHATWOOT = { Carmen: 5, Gisela: 4, Laurence: 6 };

// --- eGO (CRM) -----------------------------------------------------------------
// Comprobado con la API el 2-10-2026. Agencia 4338.
const EGO_ESTADOS = { 2: 'Disponible', 3: 'Vendido', 4: 'Reservado', 5: 'Alquilado', 7: 'Captación',
                      8: 'Retirado', 9: 'En evaluación' };
const EGO_DISPONIBLE = 2;
const EGO_PORTALES = { 701: 'Idealista', 31: 'Fotocasa', 680: 'Properstar' };
// Usuarios de eGO de cada comercial (securityUserID)
const EGO_COMERCIALES = { 88560: 'Carmen', 62597: 'Gisela', 10768: 'Laurence' };
// Llaves: en eGO solo constan las de algunos inmuebles. Con false, que no consten no
// impide ofrecer visita: se le dice a la asesora en el aviso para que lo coordine.
const LLAVES_OBLIGATORIAS = false;

// --- Avisos al equipo (solo WhatsApp) ----------------------------------------------
// Largo maximo del resumen dentro del aviso y del aviso entero. Meta corta la
// plantilla si pasa de ~1000 caracteres: asi cabe siempre y se lee de un vistazo.
const AVISO_RESUMEN_MAX = 220;
const AVISO_MAX = 600;

// --- Tiempos -----------------------------------------------------------------
const BUFFER_SEGUNDOS = 60;         // se juntan los mensajes que el cliente manda seguidos
const RECORDATORIO_HORAS = 24;      // aviso al comercial antes de cada visita
// Antelacion minima para agendar desde WhatsApp. 0 = la que permita el horario.
const ANTELACION_MINIMA_HORAS = 0;
// Llamadas del asistente telefonico: todas van al panel, pero el aviso por
// WhatsApp a la comercial solo si la llamada ha durado al menos esto.
const LLAMADA_AVISO_MIN_SEGUNDOS = 15;

// Marca que llevan en la descripcion las visitas agendadas por WhatsApp. Con
// ella el recordatorio sabe cuales son suyas y no avisa de las del telefono.
const MARCA_ORIGEN = 'Origen: WhatsApp (Sara IA)';

// --- Pruebas -----------------------------------------------------------------
// Con estos telefonos el asistente funciona IGUAL que con un cliente, pero:
//   - los avisos van al que prueba (no a Carmen, Gisela ni Paco), con [PRUEBA];
//   - con PRUEBAS_AGENDA_REAL = false las visitas NO se escriben en la agenda
//     real (se consulta de verdad, pero la reserva se simula). Con true se
//     escriben como cualquier otra, con [PRUEBA] delante del titulo.
// Se rellena AL DESPLEGAR desde wa/pruebas.local.json (no esta en git), para no
// guardar telefonos personales en el repositorio.
// Desde la salida (6-10-2026) el calendario esta activo para todos, pruebas incluidas.
const PRUEBAS_AGENDA_REAL = true;
const PRUEBAS = /*PRUEBAS*/{ telefonos: [], avisar_movil: '', avisar_email: '' }/*FIN_PRUEBAS*/;

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------
function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  // Un 0 suelto delante es el prefijo nacional del pais de quien escribe
  // (0731 468 648 en Rumania, 06... en Italia). En E.164 no existe y en Espana
  // tampoco se usa, asi que no es nuestro: es de un pais que no sabemos cual es.
  // Dejarlo da un +0... que Meta rechaza y el lead se pierde sin que nadie se
  // entere; quitarlo es peor, porque 0731468648 se convertiria en el movil
  // espanol +34731468648 y le escribiriamos a otra persona. Se marca como no
  // valido y el lead se va por correo o a revisar, con su numero tal cual.
  const truncoDesconocido = s.startsWith('0');
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;
  return {
    e164: s ? '+' + s : '',
    wa_id: s,                                   // como lo quiere Meta: solo digitos
    nacional: s.startsWith('34') ? s.slice(2) : s,
    valido: !truncoDesconocido && s.length >= 8 && s.length <= 15,
  };
}

// --- Vacaciones y ausencias ---------------------------------------------------
// Mientras una asesora no esta, SUS visitas las hace la otra: la cita se agenda
// en la agenda de la sustituta, con SU horario (ojo: Gisela no abre los
// sabados), y el aviso le llega a ella. Es por FECHA DE LA VISITA, no por el dia
// en que se pide: una llamada de hoy para dentro de dos semanas se agenda con
// quien vaya a estar ese dia.
// RELLENAR cuando una se vaya de vacaciones, y quitarlo cuando vuelva.
const AUSENCIAS = [
  // Vacia: no hay nadie fuera. Carmen volvio de vacaciones el 24/10/2026.
  // Ejemplo de como se rellena:
  //   { asesora: 'Carmen', sustituye: 'Gisela', motivo: 'vacaciones',
  //     desde: '2026-10-16', hasta: '2026-10-26' },
];

// Quien atiende de verdad a esa asesora en esa fecha ('yyyy-MM-dd').
function quienAtiende(asesora, fecha) {
  const f = String(fecha ?? '');
  const a = AUSENCIAS.find(x => x.asesora === asesora && f >= x.desde && f <= x.hasta);
  return a && a.sustituye ? a.sustituye : asesora;
}

// La ausencia que aplica (para poder explicarlo en los avisos), o null.
function ausenciaDe(asesora, fecha) {
  const f = String(fecha ?? '');
  return AUSENCIAS.find(x => x.asesora === asesora && f >= x.desde && f <= x.hasta) || null;
}

const sinAcentos = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

// De varias referencias posibles (la de la cartera, la que manda el agente, la
// del lead de ese telefono), la primera que tiene comercial (BN/OR -> Carmen,
// CS/VR -> Gisela). Asi un numero de enlace ("26699629-A") nunca deja el aviso
// sin comercial si hay otra referencia buena.
function referenciaBuena(...candidatas) {
  const limpias = candidatas.map(x => String(x ?? '').toUpperCase().trim()).filter(Boolean);
  return limpias.find(x => ASESORA_POR_PREFIJO[prefijoDeReferencia(x)]) || limpias[0] || '';
}

// Como se le nombra al cliente a quien se encarga: la asesora de la zona por su
// nombre (Carmen o Gisela). Laurence es de la oficina, no "asesora de la zona".
function quienSeEncarga(nombre, zona) {
  const n = String(nombre ?? '').trim();
  const z0 = String(zona ?? '').split(' / ')[0].trim();
  const z = /^benicasim$/i.test(z0) ? 'Benicàssim' : z0;
  if (['Carmen', 'Gisela'].includes(n)) return `${n}, la asesora de la zona${z ? ' de ' + z : ''}`;
  return n ? `${n}, de nuestro equipo` : 'nuestro equipo';
}

// Asesora por referencia y, si no hay, por municipio. Si no hay ninguna, Laurence.
function resolverAsesora(ref, municipio) {
  const prefijo = prefijoDeReferencia(ref);
  let asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  if (!asesora && municipio) {
    const m = sinAcentos(municipio);
    for (const [clave, quien] of Object.entries(ASESORA_POR_MUNICIPIO)) {
      if (m.includes(clave)) { asesora = quien; break; }
    }
  }
  const final = asesora || 'Laurence';
  return { prefijo, asesora, conocida: !!asesora, destinatario: final, ...EQUIPO[final] };
}

// Alquiler o compra. Mismo criterio que el telefono: lo dice la operacion o la
// referencia acaba en -A.
function esAlquiler(referencia, operacion) {
  // La referencia manda: en Casagencia las que acaban en -A son de alquiler y las
  // de -V de venta. eGO a veces marca "Venta" una solicitud de Idealista de un
  // piso de alquiler (BN-C-126-A, 6-10-2026).
  const ref = String(referencia ?? '').trim();
  if (/-A$/i.test(ref)) return true;
  if (/-V$/i.test(ref)) return false;
  const o = String(operacion ?? '').toLowerCase();
  if (o.includes('alquiler') || o.includes('traspaso') || o.includes('rent')) return true;
  if (o.includes('venta') || o.includes('compra')) return false;
  return /-A$/i.test(String(referencia ?? '').trim());
}

function detectarPortal(remitente, asunto) {
  for (const p of PORTALES) {
    if (p.de.test(String(remitente ?? '')) || p.asunto.test(String(asunto ?? ''))) return p.nombre;
  }
  return 'Otro';
}

// Meta no admite saltos de linea, tabuladores ni mas de 4 espacios seguidos
// dentro de un parametro de plantilla: si los hay, rechaza el envio entero.
function paramPlantilla(texto, max = 700) {
  return String(texto ?? '')
    .replace(/[\r\n\t]+/g, ' · ')
    .replace(/ {2,}/g, ' ')
    .trim()
    .slice(0, max) || '-';
}

// Recorta un texto a `max` caracteres sin partir palabras (y con … si sobra).
function recortar(texto, max) {
  const t = String(texto ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const corte = t.slice(0, max - 1);
  const espacio = corte.lastIndexOf(' ');
  return (espacio > max * 0.6 ? corte.slice(0, espacio) : corte).replace(/[\s,.;:·-]+$/, '') + '…';
}

// "2026-10-02" + "17:00" -> "jueves 2 de octubre a las 17:00"
function fechaLegible(fecha, hora) {
  const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
                 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const d = DateTime.fromFormat(String(fecha), 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return `${fecha} ${hora || ''}`.trim();
  return `${DIAS[d.weekday - 1]} ${d.day} de ${MESES[d.month - 1]}` + (hora ? ` a las ${hora}` : '');
}

// "17:00" -> "5 de la tarde", "10:30" -> "10 y media de la mañana", "12:15" ->
// "12 y cuarto del mediodía". Para las plantillas que dicen "a las {{2}}".
function horaTexto(hora) {
  const m = String(hora ?? '').match(/^(\d{1,2}):(\d{2})/);
  if (!m) return String(hora ?? '');
  const h = Number(m[1]), min = Number(m[2]);
  if (h === 13 || h === 1) return `${m[1].padStart(2, '0')}:${m[2]}`;   // "a las una" no encaja
  const h12 = h % 12 || 12;
  const franja = h < 6 ? 'de la madrugada' : h < 12 ? 'de la mañana' : h === 12 ? 'del mediodía'
    : h < 21 ? 'de la tarde' : 'de la noche';
  const minutos = min === 0 ? '' : min === 30 ? ' y media' : min === 15 ? ' y cuarto' : `:${m[2]}`;
  return `${h12}${minutos} ${franja}`;
}

// "Si, tengo que vender el mio" -> true. "No", "no necesito" -> false.
function esAfirmativo(texto) {
  const t = sinAcentos(texto).trim();
  if (!t || /^(no\b|nop|para nada|ninguna|nada)/.test(t) || /\bno (necesito|tengo|hace falta)\b/.test(t)) return false;
  return /^(si\b|sí\b|claro|por supuesto|correcto|exacto)/.test(t) ||
    /\b(tengo|necesito|debo|tendria|tendre|hay) que vender\b|\bnecesito vender\b|\bvender (primero|antes|mi|el|la)\b/.test(t);
}

// Id del agente de Chatwoot de un comercial ('Carmen' -> 5). 0 si no tiene.
function agenteDe(nombre) {
  return Number(AGENTES_CHATWOOT[String(nombre ?? '').trim()] || 0);
}

// Quien se queda la conversacion en el panel HOY: la comercial de la zona o,
// si esta de vacaciones (AUSENCIAS), la que la sustituye. Es por el dia de hoy
// porque es quien tiene que atender al cliente ahora; la VISITA, en cambio, va
// a quien vaya a estar el dia de la cita (eso lo decide resolverAsesora con la
// fecha). En cuanto vuelve de vacaciones, las nuevas vuelven a ser suyas solas.
function agenteDeHoy(nombre) {
  const hoy = DateTime.now().setZone(ZONA).toFormat('yyyy-MM-dd');
  return agenteDe(quienAtiende(nombre, hoy));
}

function esPrueba(telefono) {
  const t = normalizarTelefono(telefono).wa_id;
  return !!t && (PRUEBAS.telefonos || []).includes(t);
}

// Lo nuevo de leads y eGO (primer WhatsApp a los leads, notas en eGO) solo
// actua de verdad con MODO_LEADS = 'real'; con los telefonos de prueba, siempre.
function leadsEnReal(telefono) {
  return MODO_LEADS === 'real' || esPrueba(telefono);
}


// [WA][SUB] guardarCualificacion · Preparar
// Guarda lo que el cliente ha contestado y decide que pasa despues:
//
//   COMPRA   -> dos preguntas: si necesita vender para comprar (y si es que
//               si, donde esta esa vivienda: la conversacion se marca con la
//               etiqueta "vendedor") y como lo va a financiar. Se guardan y
//               Sara ofrece la visita.
//   ALQUILER -> tres preguntas: personas, ingresos y mascotas. Se guardan, se
//               avisa al comercial y la conversacion pasa a una persona: en
//               alquiler la IA no agenda, decide el equipo.
// Cuanto lleva buscando y la fecha de entrada ya no se preguntan (las averigua
// la asesora al llamar), pero los campos siguen: pueden venir del telefono o
// decirlos el cliente por su cuenta, y entonces se guardan igual.
// Lo que manda Sara llega por Start; antes pasa por ResolverReferencia, que
// cambia el numero del enlace de la web (p. ej. "26699629-A") por la referencia
// de la cartera ("BN-C-126-A"), que es la que decide a que asesora va el aviso.
const nodo = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const j = nodo('Start') || $input.first().json || {};
const tel = normalizarTelefono(j.telefono);
const c = nodo('ResolverReferencia') || {};
const referencia = referenciaBuena(c.ref_cartera, j.referencia, c.ref_del_lead);
const alquiler = esAlquiler(referencia, j.operacion);
const r = resolverAsesora(referencia);

const limpio = (v) => {
  const s = String(v ?? '').trim();
  return s && !['undefined', 'null'].includes(s.toLowerCase()) ? s : '';
};

const campos = {
  q_tiempo_buscando: limpio(j.tiempo_buscando),
  q_necesita_vender: limpio(j.necesita_vender),
  q_vivienda_venta:  limpio(j.vivienda_a_vender),
  q_financiacion:    limpio(j.financiacion),
  q_personas:        limpio(j.personas),
  q_ingresos:        limpio(j.ingresos),
  q_mascotas:        limpio(j.mascotas),
  q_entrada:         limpio(j.entrada),
  q_duracion:        limpio(j.duracion),
  q_actividad:       limpio(j.actividad),
};

const respuestas = alquiler
  ? [['Personas', campos.q_personas], ['Ingresos', campos.q_ingresos],
     ['Mascotas', campos.q_mascotas], ['Entrada', campos.q_entrada],
     ['Todo el ano o temporada', campos.q_duracion], ['Actividad', campos.q_actividad]]
  : [['Lleva buscando', campos.q_tiempo_buscando], ['Necesita vender para comprar', campos.q_necesita_vender],
     ['Vivienda que tiene que vender', campos.q_vivienda_venta], ['Financiacion', campos.q_financiacion]];

// Vendedor: lo dice Sara (es_vendedor), o ha dado la zona de la vivienda que
// vende, o su respuesta es un si. Es tambien un posible encargo de venta.
const vendedor = !alquiler && (j.es_vendedor === true || String(j.es_vendedor).toLowerCase() === 'true'
  || !!campos.q_vivienda_venta || esAfirmativo(campos.q_necesita_vender));

const resumen = limpio(j.resumen);

return [{
  json: {
    telefono_e164: tel.e164,
    telefono_wa: tel.wa_id,
    nombre: limpio(j.nombre),
    referencia,
    operacion: alquiler ? 'alquiler' : 'venta',
    es_alquiler: alquiler,
    es_vendedor: vendedor,
    etiqueta_vendedor: ETIQUETA_VENDEDOR,
    asesora: r.destinatario,
    // En alquiler pasa al equipo solo cuando estan las cuatro respuestas (lo mira
    // ¿Alquiler completo? con lo que queda guardado, que junta las de varias veces)
    estado: alquiler ? 'alquiler_cualificando' : 'cualificado',
    ...campos,
    campos_con_dato: Object.entries(campos).filter(([, v]) => v).map(([k]) => k),
    resumen_sara: resumen,
    conversacion_id: Number(j.conversacion_id || 0),
    // Lo que necesita el aviso al equipo (solo se usa en alquiler)
    aviso: {
      accion: 'INTERVENIR',
      destinatario: r.destinatario,
      referencia,
      cliente_nombre: limpio(j.nombre),
      cliente_telefono: tel.e164,
      // Al WhatsApp, lo corto: las respuestas en pocas palabras (el detalle va a eGO)
      resumen: [ 'ALQUILER cualificado', respuestas.filter(([, v]) => v).map(([, v]) => recortar(v, 45)).join(' · '),
                 resumen ].filter(Boolean).join(' · '),
      detalle: [
        'Lead de ALQUILER cualificado por WhatsApp. La IA no agenda en alquiler:',
        'decide tu si le das visita.', '',
        ...respuestas.map(([k, v]) => `${k}: ${v || 'no facilitado'}`), '',
        `Resumen: ${resumen || 'sin resumen'}`,
      ].join('\n'),
      conversacion_id: Number(j.conversacion_id || 0),
      pasar_a_humano: true,
      etiqueta: '',
    },
    // En compra lo que falta y como cerrar lo decide Respuesta, que ya tiene
    // delante la ficha guardada y sabe si la visita esta pre-reservada.
    falta_compra: alquiler ? [] : [
      ...(vendedor && !campos.q_vivienda_venta
        ? ['la direccion o zona de la vivienda que tiene que vender'] : []),
      ...(!campos.q_financiacion
        ? ['como lo va a financiar (hipoteca, recursos propios o hipoteca ya preconcedida)'] : []),
    ],
    marcado_vendedor: vendedor,
    respuesta: alquiler
      // (la de alquiler la completa Respuesta con el nombre de la asesora que recibe el aviso)
      ? `Respuestas guardadas. Dile al cliente que le pasas sus datos a ${quienSeEncarga(r.destinatario)} y que se `
        + 'pondra en contacto con el para organizar la visita. No le ofrezcas fecha ni hora.'
      : 'Respuestas guardadas.',
    // El aviso de compra solo sale cuando la visita YA esta pre-reservada: la
    // asesora recibio la pre-reserva sin estos datos porque todavia no existian.
    aviso_compra: {
      accion: 'DATOS PARA LA VISITA',
      destinatario: r.destinatario,
      referencia,
      cliente_nombre: limpio(j.nombre),
      cliente_telefono: tel.e164,
      resumen: ['Datos del cliente para la visita',
                respuestas.filter(([, v]) => v).map(([k, v]) => `${k}: ${recortar(v, 45)}`).join(' · '),
                resumen].filter(Boolean).join(' · '),
      detalle: ['Lead de COMPRA con la visita ya pre-reservada. Estos son los datos que ha dado',
                'DESPUES de reservarla, para que vayas con contexto.', '',
                ...respuestas.map(([k, v]) => `${k}: ${v || 'no facilitado'}`), '',
                `Resumen: ${resumen || 'sin resumen'}`].join('\n'),
      conversacion_id: Number(j.conversacion_id || 0),
      // No es una intervencion: la visita sigue su curso y la IA sigue atendiendo
      pasar_a_humano: false,
      etiqueta: '',
    },
  }
}];

