// fecha de entrada puede venir del telefono o haberla dicho el cliente solo.
const MUESTRA = [...PIDE.map(([k]) => k), 'q_entrada'].filter((k, i, a) => a.indexOf(k) === i);
const datos = MUESTRA.map((k) => [ETQ[k], v(k)]).filter(([, x]) => x);
return [{ json: {
  completo: faltan.length === 0, faltan, ficha_id: g.id || null,
  resumen_aviso: ['ALQUILER cualificado', ...datos.map(([, x]) => recortar(x, 45)), p.resumen_sara]
